// Majoor VideoTools - regenerate one shot.
//
// A shot is regenerated by giving a new seed to the generation block of that shot and queueing the graph: ComfyUI keeps the
// result of every block that did not change, so only this shot is generated again, Apply Shot Metadata adds its new take and
// Shot Assemble assembles the edit again. The block is the nodes stamped by Deploy Shots with the shot id, plus the nodes
// downstream of the Select Shot that reads it (up to Apply Shot Metadata).

import { app } from "../../scripts/app.js";

const SELECT = "MajoorSelectShot";
const APPLY = "MajoorApplyShotMetadata";
const SEED = /^(noise_|rand_)?seed$/i;
const MAX_SEED = 2 ** 48;

function downstream(select) {
  const found = [];
  const seen = new Set([select.id]);
  const todo = [select];
  while (todo.length) {
    const node = todo.pop();
    if (node.comfyClass === APPLY) continue;
    for (const out of node.outputs ?? []) {
      for (const id of out.links ?? []) {
        const next = app.graph.getNodeById(app.graph.links.get(id)?.target_id);
        if (next && !seen.has(next.id)) {
          seen.add(next.id);
          found.push(next);
          todo.push(next);
        }
      }
    }
  }
  return found;
}

function blockOf(shotId) {
  const nodes = new Set();
  for (const node of app.graph._nodes) {
    if (node.properties?.majoor_deploy?.shot === shotId) nodes.add(node);
    if (node.comfyClass === SELECT && node.widgets?.find((w) => w.name === "shot_id")?.value === shotId) {
      nodes.add(node);
      downstream(node).forEach((n) => nodes.add(n));
    }
  }
  return [...nodes];
}

// Gives a new seed to the generation block of `shotId` and queues the graph. Returns a sentence for the user.
export async function regenerateShot(shotId) {
  const seeds = blockOf(shotId).flatMap((n) => (n.widgets ?? []).filter((w) => SEED.test(w.name) && typeof w.value === "number"));
  if (!seeds.length) return `No seed found for ${shotId}: deploy its block with Deploy Shots, or connect its Select Shot to a node with a seed.`;
  for (const w of seeds) {
    w.value = Math.floor(Math.random() * Math.min(w.options?.max ?? MAX_SEED, MAX_SEED));
    w.callback?.(w.value);
  }
  app.graph.setDirtyCanvas(true, true);
  await app.queuePrompt(0, 1);
  return `${shotId} queued with a new seed (${seeds.length} seed${seeds.length > 1 ? "s" : ""}).`;
}
